head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.select11_onviewchange = function(info) {
    localStorage.setItem("log", "onviewchange info.oldValue/info.newValue = " +
        info.oldValue + "/" + info.newValue);
    console.log("onviewchange info.oldValue/info.newValue = " +
        info.oldValue + "/" + info.newValue);
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate = function() {
    scwin.simulateWrapper('#select11_label', 'key-sequence', {
        sequence: 'b'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#select11_label', 'key-sequence', {
        sequence: 'c'
    });
}
scwin.setSimulate3 = function() {
    scwin.simulateWrapper('#select11_label', 'key-sequence', {
        sequence: 'd'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 'onviewchange info.oldValue/info.newValue = 1value/2value'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 'onviewchange info.oldValue/info.newValue = 2value/3value'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 'onviewchange info.oldValue/info.newValue = 3value/4value'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
